import{_ as h,o as t,c as a,a2 as c}from"./chunks/framework.mRCPFc5l.js";const s=JSON.parse('{"title":"Hệ thống cập nhật hiểu biết về learner ra sao","description":"","frontmatter":{},"headers":[],"relativePath":"learner/cap-nhat.md","filePath":"learner/cap-nhat.md"}'),i={name:"learner/cap-nhat.md"};function g(o,n,u,r,e,l){return t(),a("div",null,[...n[0]||(n[0]=[c('<h1 id="he-thong-cap-nhat-hieu-biet-ve-learner-ra-sao" tabindex="-1">Hệ thống cập nhật hiểu biết về learner ra sao <a class="header-anchor" href="#he-thong-cap-nhat-hieu-biet-ve-learner-ra-sao" aria-label="Permalink to &quot;Hệ thống cập nhật hiểu biết về learner ra sao&quot;">​</a></h1><p>Trên trang này# Hệ thống cập nhật hiểu biết về learner ra sao <a href="#he-thong-cap-nhat-hieu-biet-ve-learner-ra-sao">​</a> Hiểu biết của Nemo12 về một learner không phải kết quả của một lần đánh giá. Nó là một vòng lặp chạy liên tục, và mỗi hoạt động của con đều đi vào vòng đó. textBằng chứng mới ↓ Cập nhật Learner Model ↓ Đã đủ chắc chắn chưa? ├── Chưa → đo thêm để thu bằng chứng └── Rồi → chọn việc nên làm tiếp ↓ Trải nghiệm học ↓ Bằng chứng mới ↺</p><h2 id="khong-phai-su-kien-nao-cung-đung-toi-moi-thu-​" tabindex="-1">Không phải sự kiện nào cũng đụng tới mọi thứ <a href="#khong-phai-su-kien-nao-cung-đung-toi-moi-thu">​</a> <a class="header-anchor" href="#khong-phai-su-kien-nao-cung-đung-toi-moi-thu-​" aria-label="Permalink to &quot;Không phải sự kiện nào cũng đụng tới mọi thứ [​](#khong-phai-su-kien-nao-cung-đung-toi-moi-thu)&quot;">​</a></h2><p>Đây là chi tiết quan trọng và hay bị làm sai: một hệ thống cập nhật <em>tất cả</em> sau <em>mỗi</em> sự kiện thì vừa chậm vừa sai. Nemo12 có quy tắc rõ ràng cho từng loại sự kiện: Chuyện xảy raCập nhật cái gì<strong>Không</strong> đụng tớiCon làm bài luyện tậpMức vững, trạng thái trí nhớ, mức sẵn sàngMục tiêu, hoàn cảnhCon ôn lại và nhớ đượcTrạng thái trí nhớ, lịch ôn kế tiếpMức vững lịch sửPhụ huynh báo con ốmHoàn cảnh, kế hoạch tuần<strong>Mức vững — tuyệt đối không</strong>Con nói sợ môn HìnhHoàn cảnh (cảm xúc)Mức vững, mục tiêuLịch thi dờiHoàn cảnh, mục tiêu, mức khẩn, kế hoạchMức vữngGia đình đổi mục tiêuMục tiêu, mức sẵn sàng, kế hoạchMức vững, hoàn cảnhĐọc kỹ cột phải sẽ thấy nguyên tắc: <strong>chỉ có bằng chứng về việc học mới được đụng vào mức vững</strong>. Mọi thứ khác — ốm, lo lắng, lịch thi, đổi mục tiêu — chỉ đổi <em>việc nên làm hôm nay</em>.</p><h2 id="thu-tu-cap-nhat-cung-co-luat-​" tabindex="-1">Thứ tự cập nhật cũng có luật <a href="#thu-tu-cap-nhat-cung-co-luat">​</a> <a class="header-anchor" href="#thu-tu-cap-nhat-cung-co-luat-​" aria-label="Permalink to &quot;Thứ tự cập nhật cũng có luật [​](#thu-tu-cap-nhat-cung-co-luat)&quot;">​</a></h2><p>Luôn theo một chiều: hoàn cảnh và mục tiêu được cập nhật <strong>trước</strong>, gợi ý được tính lại <strong>sau cùng</strong>. Lý do đơn giản: gợi ý phụ thuộc vào mọi thứ khác. Tính gợi ý trước rồi mới cập nhật lịch thi thì gợi ý vừa sinh ra đã lỗi thời.</p><h2 id="vi-sao-hom-nay-khac-hom-qua-​" tabindex="-1">Vì sao hôm nay khác hôm qua <a href="#vi-sao-hom-nay-khac-hom-qua">​</a> <a class="header-anchor" href="#vi-sao-hom-nay-khac-hom-qua-​" aria-label="Permalink to &quot;Vì sao hôm nay khác hôm qua [​](#vi-sao-hom-nay-khac-hom-qua)&quot;">​</a></h2><p>Vì mọi cập nhật đều được ghi kèm phiên bản, Nemo12 có thể trả lời chính xác câu này. Hệ thống so hai lần tính và quy về những sự kiện đã gây ra khác biệt: <em>&quot;Gợi ý hôm nay khác hôm qua vì: có thêm lịch thi học kỳ, có ghi nhận con ốm, thời gian rảnh trong tuần giảm 60 phút, và mức sẵn sàng phần Hình học vừa được tính lại.&quot;</em> Đây là thứ một hệ thống &quot;hộp đen&quot; không làm được. Nếu bạn không giải thích được vì sao lời khuyên đổi, thì bạn cũng không kiểm tra được nó có hợp lý không — và bạn không có cơ sở nào để tin nó cả.</p><h2 id="viec-nay-khong-chay-trong-luc-con-bam-nut-​" tabindex="-1">Việc này không chạy trong lúc con bấm nút <a href="#viec-nay-khong-chay-trong-luc-con-bam-nut">​</a> <a class="header-anchor" href="#viec-nay-khong-chay-trong-luc-con-bam-nut-​" aria-label="Permalink to &quot;Việc này không chạy trong lúc con bấm nút [​](#viec-nay-khong-chay-trong-luc-con-bam-nut)&quot;">​</a></h2><p>Khi con nộp một bài, một chuỗi việc được kích hoạt: kiểm tra tính hợp lệ, lưu bằng chứng, cập nhật các mảng kiến thức liên quan, lan sang các mảng phụ thuộc, tính lại độ chắc chắn, phát hiện thay đổi đáng kể, sinh gợi ý mới, cập nhật hoàn cảnh, thông báo nếu cần. Chuỗi này chạy ở hậu trường sau khi con đã thấy kết quả. Con không phải chờ hệ thống nghĩ.</p><h2 id="lan-truyen-sang-cac-mang-lien-quan-​" tabindex="-1">Lan truyền sang các mảng liên quan <a href="#lan-truyen-sang-cac-mang-lien-quan">​</a> <a class="header-anchor" href="#lan-truyen-sang-cac-mang-lien-quan-​" aria-label="Permalink to &quot;Lan truyền sang các mảng liên quan [​](#lan-truyen-sang-cac-mang-lien-quan)&quot;">​</a></h2><p>Kiến thức là một mạng lưới, không phải danh sách. Khi bằng chứng về &quot;phân số&quot; thay đổi, các mảng phụ thuộc vào phân số cũng bị ảnh hưởng — không phải bị hạ thẳng, mà là <strong>độ chắc chắn của chúng giảm đi</strong>: nếu nền vừa lung lay, thì những kết luận xây trên nền đó cũng kém tin cậy hơn. Đây là cách hệ thống phát hiện được những chuyện như: <em>&quot;con làm sai bài lượng giác không phải vì lượng giác, mà vì phần biến đổi đại số cơ bản&quot;</em>.</p><h2 id="ban-thay-gi-tu-tat-ca-nhung-đieu-nay-​" tabindex="-1">Bạn thấy gì từ tất cả những điều này <a href="#ban-thay-gi-tu-tat-ca-nhung-đieu-nay">​</a> <a class="header-anchor" href="#ban-thay-gi-tu-tat-ca-nhung-đieu-nay-​" aria-label="Permalink to &quot;Bạn thấy gì từ tất cả những điều này [​](#ban-thay-gi-tu-tat-ca-nhung-đieu-nay)&quot;">​</a></h2><p>Không thấy phương trình nào cả. Cái gia đình thấy là những nhóm rất đơn giản:</p><ul><li><strong>Đang chắc</strong> — vững, còn nhớ tốt.</li><li><strong>Cần nhắc lại sớm</strong> — vẫn ổn nhưng đang mờ dần.</li><li><strong>Có nguy cơ quên</strong> — từng vững, lâu không dùng.</li><li><strong>Nên ôn lại</strong> — đã rơi đáng kể.</li><li><strong>Chưa đủ dữ liệu</strong> — hệ thống chưa dám nói gì. Toàn bộ phần tính toán bên dưới tồn tại để năm cái nhãn này nói đúng sự thật — chứ không phải để bạn phải đọc hiểu chúng. Hiểu một đứa trẻ là việc làm liên tục, có sửa sai, có ghi lại lý do. Không phải một buổi đánh giá rồi kết luận. <a href="/portrait/">Sang nhóm: Student Portrait →</a></li></ul>',15)])])}const p=h(i,[["render",g]]);export{s as __pageData,p as default};
